import java.util.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        int factor = sc.nextInt();

        int[] parent = new int[total + 1];
        int[] rank = new int[total + 1];
        for (int i = 1; i <= total; i++) {
            parent[i] = i;
            rank[i] = 1;
        }

        Function<Integer, Integer> findp = new Function<Integer, Integer>() {
            Map<Integer, Integer> memo = new HashMap<>();
            public Integer apply(Integer x) {
                if (parent[x] != x) {
                    parent[x] = apply(parent[x]);
                }
                return parent[x];
            }
        };

        BiConsumer<Integer, Integer> unite = new BiConsumer<Integer, Integer>() {
            public void accept(Integer a, Integer b) {
                if (rank[a] >= rank[b]) {
                    parent[b] = a;
                    rank[a]++;
                } else {
                    parent[a] = b;
                    rank[b]++;
                }
            }
        };

        for (int i = 1; i <= total; i++) {
            int val = (int)((long)factor * i % total);
            int pa = findp.apply(i);
            int pb = findp.apply(val);
            if (pa != pb) {
                unite.accept(pa, pb);
            }
        }

        Set<Integer> group_ids = new HashSet<>();
        for (int i = 1; i <= total; i++) {
            group_ids.add(findp.apply(i));
        }

        final long MOD = 1000000007L;

        BiFunction<Long, Long, Long> fast_pow = new BiFunction<Long, Long, Long>() {
            public Long apply(Long base, Long exp) {
                long res = 1;
                long b = base;
                long e = exp;
                while (e > 0) {
                    if ((e & 1) == 1) {
                        res = (res * b) % MOD;
                    }
                    b = (b * b) % MOD;
                    e >>= 1;
                }
                return res;
            }
        };

        long result;
        if (factor == 0) {
            result = fast_pow.apply((long)total, (long)(total - 1));
        } else if (factor == 1) {
            result = fast_pow.apply((long)total, (long)total);
        } else {
            result = fast_pow.apply((long)total, (long)group_ids.size());
        }

        System.out.println(result);
    }
}
